export function fixR60Controls(html){
 const scripts=[...html.matchAll(/<script([^>]*)>([\s\S]*?)<\/script\s*>/g)];
 if(scripts.length!==23)throw Error('Unexpected R60 script count');
 for(const i of [16,13,5]){
  let text=scripts[i][2];
  for(const p of CHANGES.filter(p=>p.script===i)){
   if(text.split(p.before).length!==p.count+1)throw Error('Unexpected R60 source revision');
   text=text.split(p.before).join(p.after);
  }
  const m=scripts[i],a=m.index+m[0].indexOf('>')+1;
  html=html.slice(0,a)+text+html.slice(a+m[2].length);
 }
 return html;
}

